function translatedSourceUrl(url){return `https://translate.google.com/translate?sl=auto&tl=sq&u=${encodeURIComponent(url)}`}
document.querySelectorAll(".safety-card>a[href^='https://']").forEach(sourceLink=>{
  const translationLink=document.createElement("a");
  translationLink.href=translatedSourceUrl(sourceLink.href);
  translationLink.target="_blank";
  translationLink.rel="noopener noreferrer";
  translationLink.className="translated-source-link";
  translationLink.textContent="Lexo në shqip ↗";
  translationLink.setAttribute("aria-label",`Lexo në shqip me përkthim automatik: ${sourceLink.textContent.trim()}`);
  sourceLink.after(translationLink);
});

