const loadedManagedItems=new Set();
function mergeManagedContent(content={}){
  (content.quizQuestions||[]).forEach(item=>{const key=`quiz:${item.q}`;if(loadedManagedItems.has(key))return;loadedManagedItems.add(key);quizQuestions.push({...item,section:"Praktika e avancuar"})});
  (content.labCases||[]).forEach(item=>{const key=`lab:${item.title}`;if(loadedManagedItems.has(key))return;loadedManagedItems.add(key);labCases.push(item)});
  const grid=document.querySelector("#safety .safety-grid");
  (content.safetyTips||[]).forEach(item=>{const key=`tip:${item.title}`;if(loadedManagedItems.has(key))return;loadedManagedItems.add(key);if(!grid)return;const card=document.createElement("article");card.className="safety-card";const icon=document.createElement("span");icon.className="safety-icon icon-violet";icon.textContent=item.icon||"✦";const title=document.createElement("h3");title.textContent=item.title;const body=document.createElement("p");body.textContent=item.text;const link=document.createElement("a");link.href=item.sourceUrl;link.target="_blank";link.rel="noopener noreferrer";link.textContent=`${item.sourceName} ↗`;card.append(icon,title,body,link);grid.append(card)});
  const quizIntro=document.querySelector("#quiz .intro p");if(quizIntro)quizIntro.textContent=`${quizQuestions.length} pyetje në ${quizSections.length} blloqe. Pas çdo përgjigjeje shfaqet shpjegimi dhe në fund rezultati sipas temës.`;
  const safetyIntro=document.querySelector("#safety .intro p");if(safetyIntro)safetyIntro.textContent=`${grid?.children.length||0} këshilla të shkurtra për llogaritë, pajisjet dhe situatat e përditshme. Hap burimet zyrtare për udhëzime më të hollësishme.`;
  if(typeof renderLabCase==="function"&&labCases.length)renderLabCase();
}

const titles={dashboard:"Përshëndetje, mirë se erdhe!",lessons:"Mësimet e tua",quiz:"Kuizi i sigurisë",assistant:"Chatbot edukativ",lab:"Laboratori i sigurisë",safety:"Këshilla sigurie"};
function readProgress(key,fallback){try{const value=localStorage.getItem(key);return value?JSON.parse(value):fallback}catch{return fallback}}
let activeUser=readProgress("cyberedu_session",null);
const progressPrefix=()=>`cyberedu_profile_${activeUser?.email||"guest"}_`;
let completed=readProgress(progressPrefix()+"completed",[]);if(!Array.isArray(completed))completed=[];
let favorites=readProgress(progressPrefix()+"favorites",[]);if(!Array.isArray(favorites))favorites=[];
let chatHistory=readProgress(progressPrefix()+"chat",[]);if(!Array.isArray(chatHistory))chatHistory=[];
let totalScore=Number(readProgress(progressPrefix()+"score",0))||0,currentQuestion=0,quizScore=0,quizAnswers=[],answered=false;let activityLog=readProgress(progressPrefix()+"activity",[]);if(!Array.isArray(activityLog))activityLog=[];
function recordActivity(text){activityLog.unshift({text,at:new Date().toISOString()});activityLog=activityLog.slice(0,80);try{localStorage.setItem(progressPrefix()+"activity",JSON.stringify(activityLog))}catch{}}
function renderActivity(){const list=document.getElementById("activity-list"),entries=[...activityLog];const logged=new Set(entries.map(item=>item.text));completed.map(id=>lessons.find(lesson=>lesson.id===id)).filter(Boolean).forEach(lesson=>{const label=`Përfundove mësimin: ${lesson.title}`;if(!logged.has(label))entries.push({text:label,at:""})});document.getElementById("activity-summary").textContent=`Ke përfunduar ${completed.length} nga ${lessons.length} mësime, ke fituar ${totalScore} pikë kuizi dhe ke ${entries.length} aktivitete të regjistruara.`;list.replaceChildren();if(!entries.length){const empty=document.createElement("p");empty.className="activity-empty";empty.textContent="Ende nuk ka aktivitete. Përfundo një mësim ose kuiz për ta nisur historikun.";list.append(empty);return}entries.slice(0,30).forEach(item=>{const row=document.createElement("article");row.className="activity-entry";const icon=document.createElement("span");icon.className="activity-entry-icon";icon.textContent="✓";const copy=document.createElement("div"),title=document.createElement("b"),date=document.createElement("small");title.textContent=item.text;date.textContent=item.at?new Date(item.at).toLocaleString("sq-AL"):"Përparim i ruajtur";copy.append(title,date);row.append(icon,copy);list.append(row)})}const activityModal=document.getElementById("activity-modal");document.getElementById("activity-button").onclick=()=>{renderActivity();activityModal.classList.remove("hidden");document.getElementById("activity-close").focus()};function closeActivity(){activityModal.classList.add("hidden");document.getElementById("activity-button").focus()}document.getElementById("activity-close").onclick=closeActivity;activityModal.addEventListener("click",event=>{if(event.target===activityModal)closeActivity()});document.addEventListener("keydown",event=>{if(event.key==="Escape"&&!activityModal.classList.contains("hidden"))closeActivity()});

function updateDashboard(){
  const nextLesson=lessons.find(lesson=>!completed.includes(lesson.id));
  const continueLabel=document.getElementById("continue-label");
  if(continueLabel)continueLabel.textContent=nextLesson?`Vazhdo me: ${nextLesson.title}`:"I përfundove të gjitha mësimet! Rilexoji";
  document.getElementById("completed-count").textContent=completed.length;
  document.getElementById("score-count").textContent=totalScore;
  document.getElementById("level-count").textContent=completed.length>=9?"I avancuar":completed.length>=5?"Në zhvillim":"Fillestar";
  const pct=Math.round(completed.length/lessons.length*100);
  document.getElementById("progress-percent").textContent=pct+"%";
  document.getElementById("progress-bar").style.width=pct+"%";
  document.getElementById("progress-label").textContent=`${completed.length} nga ${lessons.length} mësime të përfunduara`;
  document.getElementById("lesson-total").textContent=` / ${lessons.length}`;document.getElementById("lesson-count").textContent=String(lessons.length);document.querySelector("#lessons .intro p").textContent=`${lessons.length} module me udhëzime praktike, shembuj dhe burime për lexim të mëtejshëm.`;document.querySelector("#quiz .intro p").textContent=`${quizQuestions.length} pyetje në ${quizSections.length} blloqe. Pas çdo përgjigjeje shfaqet shpjegimi dhe në fund rezultati sipas temës.`;const unlocked=Number(completed.length>0)+Number(completed.length>=5)+Number(totalScore>=5)+Number(completed.length===lessons.length);
  document.getElementById("achievement-count").textContent=`${unlocked} / 4`;
  const earnedCount=unlocked;
  document.getElementById("report-lessons").textContent=`${completed.length} / ${lessons.length}`;
  document.getElementById("report-lessons-bar").style.width=`${pct}%`;
  document.getElementById("report-quiz").textContent=String(totalScore);
  document.getElementById("report-quiz-bar").style.width=`${Math.min(100,totalScore/(quizQuestions.length*3)*100)}%`;
  document.getElementById("report-badges").textContent=`${earnedCount} / 4`;
  document.getElementById("report-badges-bar").style.width=`${earnedCount*25}%`;  document.querySelectorAll("[data-achievement]").forEach(badge=>{
    const earned=badge.dataset.achievement==="first"?completed.length>0:badge.dataset.achievement==="explorer"?completed.length>=5:badge.dataset.achievement==="quiz"?totalScore>=5:completed.length===lessons.length;
    badge.classList.toggle("earned",earned);
  });
}
function saveProgress(){try{localStorage.setItem(progressPrefix()+"completed",JSON.stringify(completed));localStorage.setItem(progressPrefix()+"favorites",JSON.stringify(favorites));localStorage.setItem(progressPrefix()+"score",String(totalScore))}catch{}updateDashboard()}
function lessonCard(lesson){const done=completed.includes(lesson.id);return `<article class="lesson-card" data-lesson="${lesson.id}" tabindex="0" role="button" aria-label="Hap mësimin: ${lesson.title}"><div class="lesson-icon">${lesson.icon}</div><h3>${lesson.title}${done?" ✓":""}</h3><p>${lesson.short}</p><div class="lesson-meta"><span>◷ ${lesson.time} lexim</span><span class="tag ${done?"done":""}">${done?"Përfunduar":lesson.level}</span></div><span class="lesson-category">${lesson.category}</span></article>`}
function renderLessons(){
  const suggested=[...lessons.filter(lesson=>!completed.includes(lesson.id)),...lessons.filter(lesson=>completed.includes(lesson.id))];
  const pinned=(activeSiteConfig.featuredLessonIds||[]).map(id=>lessons.find(lesson=>lesson.id===id)).filter(Boolean);
  document.getElementById("featured-lessons").innerHTML=[...pinned,...suggested.filter(lesson=>!pinned.includes(lesson))].slice(0,3).map(lessonCard).join("");
  renderLessonCatalog();
  document.querySelectorAll("#featured-lessons [data-lesson]").forEach(card=>{const open=()=>{showView("lessons");openLesson(Number(card.dataset.lesson))};card.addEventListener("click",open);card.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();open()}})});
}
let showFavoritesOnly=false;
function renderLessonCatalog(){
  const query=document.getElementById("lesson-search").value.trim().toLocaleLowerCase("sq");
  const category=document.getElementById("lesson-category").value;
  const visible=lessons.filter(lesson=>(category==="all"||lesson.category===category)&&(!showFavoritesOnly||favorites.includes(lesson.id))&&(!query||`${lesson.title} ${lesson.short} ${lesson.category} ${lesson.level}`.toLocaleLowerCase("sq").includes(query)));
  document.getElementById("all-lessons").innerHTML=visible.map(lessonCard).join("");
  document.getElementById("lesson-results").textContent=`${visible.length} nga ${lessons.length} mësime${showFavoritesOnly?" të preferuara":""}`;
  document.getElementById("saved-lessons-count").textContent=favorites.length;
  const empty=document.getElementById("lesson-empty");
  if(empty)empty.remove();
  if(!visible.length){const message=document.createElement("p");message.id="lesson-empty";message.className="lesson-empty";message.textContent=showFavoritesOnly&&!favorites.length?"Nuk ke ruajtur ende mësime të preferuara. Hape një mësim dhe zgjidh “Ruaje te të preferuarat”.":"Nuk u gjet asnjë mësim. Ndrysho fjalën e kërkimit ose filtrin.";document.getElementById("all-lessons").after(message)}
  document.querySelectorAll("#all-lessons [data-lesson]").forEach(card=>{const open=()=>openLesson(Number(card.dataset.lesson));card.addEventListener("click",open);card.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();open()}})});
}
