    <div class="lesson-detail-top"><span class="section-kicker">MODULI ${String(id).padStart(2,"0")} · ${lesson.category.toUpperCase()}</span><button class="detail-close" type="button" aria-label="Mbyll mësimin">Mbyll <span aria-hidden="true">×</span></button></div>
