function startQuiz(){currentQuestion=0;quizScore=0;quizAnswers=[];renderQuestion()}
function renderQuestion(){
  const box=document.getElementById("quiz-container");
  if(currentQuestion>=quizQuestions.length){
    totalScore+=quizScore;recordActivity(`Përfundove kuizin: ${quizScore} nga ${quizQuestions.length} përgjigje të sakta`);saveProgress();
    const sectionResults=quizSections.map(section=>{const count=quizQuestions.filter(question=>question.section===section).length;if(!count)return "";const earned=quizAnswers.filter(answer=>answer.section===section&&answer.correct).length;return `<li><span>${section}</span><b>${earned} / ${count}</b></li>`}).join("");
    const resultText=quizScore>=20?"Shkëlqyeshëm! Ke zotëruar shumicën e temave.":quizScore>=15?"Mirë! Rishiko temat ku humbe pikë dhe provo sërish.":"Rilexo kapitujt dhe përpiqu përsëri; secila pyetje shpjegon arsyen.";
    box.innerHTML=`<div class="quiz-start quiz-results"><div class="quiz-big-icon">★</div><span class="section-kicker">REZULTATI YT</span><h2>Kuizi përfundoi!</h2><p class="quiz-score-total"><b>${quizScore} / ${quizQuestions.length}</b> përgjigje të sakta</p><p>${resultText}</p><h3>Rezultati sipas temës</h3><ul class="quiz-section-results">${sectionResults}</ul><button class="primary-btn" id="restart-quiz">Provo përsëri <span>↻</span></button></div>`;
    document.getElementById("restart-quiz").onclick=startQuiz;return
  }
  answered=false;const question=quizQuestions[currentQuestion];
  const progress=((currentQuestion+1)/quizQuestions.length)*100;
  const sectionItems=quizQuestions.filter(item=>item.section===question.section),sectionQuestion=sectionItems.indexOf(question)+1;
  box.innerHTML=`<div class="question-top"><span>Pyetja ${currentQuestion+1} nga ${quizQuestions.length}</span><span>Pikët: ${quizScore}</span></div><div class="quiz-section-label">${question.section} <span>·</span> Pyetja ${sectionQuestion} nga ${sectionItems.length}</div><div class="quiz-progress" role="progressbar" aria-label="Përparimi i kuizit" aria-valuemin="0" aria-valuemax="${quizQuestions.length}" aria-valuenow="${currentQuestion+1}"><span style="width:${progress}%"></span></div><h3>${question.q}</h3><p class="answer-hint">Zgjidh përgjigjen që të duket më e saktë.</p><div class="answers">${question.a.map((answer,index)=>`<button class="answer-btn" data-answer="${index}">${String.fromCharCode(65+index)}. ${answer}</button>`).join("")}</div><div id="explanation-slot" aria-live="polite"></div><div class="quiz-actions"><button class="primary-btn hidden" id="next-question">${currentQuestion===quizQuestions.length-1?"Shiko rezultatin":"Vazhdo te pyetja tjetër →"}</button></div>`;
  box.querySelectorAll("[data-answer]").forEach(button=>button.onclick=()=>chooseAnswer(Number(button.dataset.answer)));
}
function chooseAnswer(index){
  if(answered)return;answered=true;const question=quizQuestions[currentQuestion];if(index===question.correct)quizScore++;
  quizAnswers.push({section:question.section,correct:index===question.correct});
  document.querySelectorAll("[data-answer]").forEach((button,i)=>{button.disabled=true;if(i===question.correct)button.classList.add("correct");else if(i===index)button.classList.add("wrong")});
  document.getElementById("explanation-slot").innerHTML=`<div class="explanation"><b>${index===question.correct?"Saktë!":"Jo kësaj here."}</b> ${question.why}</div>`;
  const next=document.getElementById("next-question");next.classList.remove("hidden");next.onclick=()=>{currentQuestion++;renderQuestion()};
}
document.getElementById("start-quiz").onclick=startQuiz;

const answers=[
  {keys:["phishing","email i rrem","mesazh i dyshimt","lidhje e dyshimt"],text:"Phishing-u është mashtrim që synon të të bëjë të japësh të dhëna ose të hapësh përmbajtje të rrezikshme. Kontrollo dërguesin dhe domenin, mos vepro nën presion dhe hyr në llogari përmes faqes zyrtare."},
  {keys:["fjalëkalim","fjalekalim","password"],text:"Përdor një fjalëkalim të gjatë dhe unik për secilën llogari. Një menaxher fjalëkalimesh mund të ndihmojë. Aktivizo MFA dhe mos i ndaj kodet e verifikimit."},
  {keys:["mfa","dy hapa","autentifikim","verifikim"],text:"MFA do të thotë autentifikim me shumë faktorë. Ai kërkon një faktor shtesë përveç fjalëkalimit, si një aplikacion autentifikimi ose çelës sigurie."},
  {keys:["malware","virus","ransomware"],text:"Malware është softuer keqdashës që mund të vjedhë të dhëna ose të dëmtojë pajisjen. Përditëso sistemin, instalo programe nga burime zyrtare dhe mos hap skedarë të dyshimtë."},
  {keys:["privatësi","privatesi","rrjete sociale","të dhëna personale"],text:"Kufizo informacionin personal që publikon, kontrollo cilësimet e privatësisë dhe lejet e aplikacioneve. Mbaj mend se çdo gjë e publikuar mund të kopjohet."},
  {keys:["mashtrim","siguri online","mbrohem"],text:"Për t’u mbrojtur: përdor fjalëkalime unike, aktivizo MFA, përditëso pajisjet, kontrollo lidhjet para se t’i hapësh dhe ruaj kopje rezervë të skedarëve."}
];
function assistantReply(question){
  const normalized=question.toLocaleLowerCase("sq").normalize("NFD").replace(/[\u0300-\u036f]/g,"");
  if(/kam klikuar|klikova|e hapa|u hakova|me vodhen|komprometuar/.test(normalized))return "Vepro shpejt, por pa panik: ndrysho fjalëkalimin nga faqja ose aplikacioni zyrtar, dil nga sesionet e tjera, aktivizo MFA dhe njofto shërbimin përkatës. Nëse përdore të njëjtin fjalëkalim diku tjetër, ndryshoje edhe atje.";
  if(/wifi|wi-fi|rrjet publik|internet publik/.test(normalized))return "Në Wi-Fi publik, verifiko emrin e rrjetit me stafin, çaktivizo lidhjen automatike dhe shmang hyrjet ose pagesat e ndjeshme. Shkëputu kur të mbarosh dhe përdor aplikacionet ose faqet zyrtare.";
  if(/telefon|humb|vjedh|pajisje/.test(normalized))return "Përdor kyçje me kod ose biometrikë, përditëso pajisjen dhe aktivizo funksionin zyrtar për gjetjen e saj. Nëse telefoni humbet, përdor faqen zyrtare të prodhuesit për ta kyçur dhe ndrysho fjalëkalimet e llogarive kryesore.";
  if(/kopje rezerv|backup|rikuper|skedar/.test(normalized))return "Mbaj kopje të skedarëve të rëndësishëm në një vend të veçantë nga pajisja kryesore dhe provo herë pas here rikthimin e tyre. Kopjet e përditësuara ndihmojnë në rast humbjeje ose dëmtimi të pajisjes.";
  if(/perdites|update|azhurn/.test(normalized))return "Instalo përditësimet e sistemit dhe aplikacioneve nga cilësimet ose dyqanet zyrtare. Ato shpesh përfshijnë rregullime sigurie; mos instalo përditësime nga lidhje të papritura në mesazhe.";
  const found=answers.find(answer=>answer.keys.some(key=>normalized.includes(key.normalize("NFD").replace(/[\u0300-\u036f]/g,""))));
  if(found)return found.text;
  if(/femije|prind|shkolle|nxenes|moshe/.test(normalized))return "Për fëmijët dhe nxënësit, nisni me rregulla të thjeshta: mos ndani fjalëkalime e kode, kërkoni ndihmë nga një i rritur kur diçka duket e çuditshme dhe mendoni para se të postoni të dhëna personale.";
  if(/pershendetje|tung|miremengjes|faleminderit/.test(normalized))return "Përshëndetje! Jam këtu për pyetje rreth fjalëkalimeve, mesazheve të dyshimta, privatësisë, MFA-së dhe pajisjeve. Çfarë po të shqetëson?";
  if(normalized.includes("cfare eshte")||normalized.includes("cfare do te thote"))return "Mund të të shpjegoj phishing-un, fjalëkalimet, MFA-në, malware-in, privatësinë, Wi-Fi publik, sigurinë e telefonit ose kopjet rezervë. Zgjidh një temë ose përdor sugjerimet.";
  return "Nuk jam i sigurt që e kuptova pyetjen. Mund të pyesësh për phishing-un, fjalëkalimet, MFA-në, privatësinë, Wi-Fi publik, pajisjet, kopjet rezervë ose çfarë të bësh pas një klikimi të dyshimtë.";
}
function renderChatHistory(){
  const box=document.getElementById("chat-messages");box.replaceChildren();
  const history=chatHistory.length?chatHistory:[{who:"assistant",text:"Përshëndetje! Çfarë do të doje të dije? Mund të pyesësh për fjalëkalimet, mesazhet e dyshimta, privatësinë, Wi-Fi publik ose sigurinë e pajisjeve."}];
  history.forEach(item=>{const message=document.createElement("div");message.className=`message ${item.who==="user"?"user":"assistant"}`;message.textContent=String(item.text||"");box.appendChild(message)});
  box.scrollTop=box.scrollHeight;
}
function addMessage(text,who){
  const message=document.createElement("div");message.className=`message ${who==="user"?"user":"assistant"}`;message.textContent=text;
  const box=document.getElementById("chat-messages");box.appendChild(message);box.scrollTop=box.scrollHeight;
  chatHistory.push({text,who:who==="user"?"user":"assistant"});chatHistory=chatHistory.slice(-40);
  try{localStorage.setItem(progressPrefix()+"chat",JSON.stringify(chatHistory))}catch{}
}
function sendQuestion(question){
  const text=question.trim().slice(0,500);if(!text)return;
  addMessage(text,"user");
  const box=document.getElementById("chat-messages"),typing=document.createElement("div");typing.className="message assistant typing-indicator";typing.textContent="Po përgatitet përgjigjja…";typing.setAttribute("aria-label","Chatboti po shkruan");box.appendChild(typing);box.scrollTop=box.scrollHeight;
  window.setTimeout(()=>{typing.remove();addMessage(assistantReply(text),"assistant")},350);
}
document.getElementById("chat-form").addEventListener("submit",event=>{event.preventDefault();const input=document.getElementById("chat-input");sendQuestion(input.value);input.value="";input.focus()});
