document.getElementById("lesson-agent-generate").onclick=async()=>{
  const request=document.getElementById("lesson-agent-request").value.trim();if(request.length<8){lessonAgentStatus.textContent="Shkruaj një udhëzim më të plotë.";return}
  if(!lessonAgentKey){lessonAgentStatus.textContent="Mungon çelësi i redaktorit.";return}
  const button=document.getElementById("lesson-agent-generate");button.disabled=true;lessonAgentStatus.textContent="Agjenti po përgatit propozimet…";lessonAgentProposals.replaceChildren();
  try{const catalog=lessons.map(lesson=>({...lesson,agentChapters:getLessonChapters(lesson),sources:lesson.sources||lessonSources[lesson.id]||[]}));const sync=await fetch("/api/agent/sync",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${lessonAgentKey}`},body:JSON.stringify({lessons:catalog})}),syncResult=await sync.json();if(!sync.ok)throw new Error(syncResult.error||"Ruajtja e kursit dështoi.");const response=await fetch("/api/agent/propose",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${lessonAgentKey}`},body:JSON.stringify({request,lessons:catalog})});const result=await response.json();if(!response.ok)throw new Error(result.error||"Kërkesa dështoi.");pendingLessonProposals=result.proposals;if(!pendingLessonProposals.length){lessonAgentStatus.textContent="Nuk u krijuan propozime për këtë kërkesë.";return}pendingLessonProposals.forEach((proposal,index)=>{const card=document.createElement("article");card.className="agent-proposal";const label=document.createElement("label"),check=document.createElement("input");check.type="checkbox";check.checked=true;check.dataset.proposal=String(index);const heading=document.createElement("b");heading.textContent=`${proposal.operation==="add"?"Mësim i ri":"Përditësim"}: ${proposal.lesson.title}`;const reason=document.createElement("p");reason.textContent=proposal.reason;const preview=document.createElement("small");preview.textContent=`${proposal.lesson.category} · ${proposal.lesson.agentChapters.length} kapituj · ${proposal.lesson.sources.length} burime`;label.append(check,heading);card.append(label,reason,preview);lessonAgentProposals.append(card)});const apply=document.createElement("button");apply.type="button";apply.className="primary-btn";apply.textContent="Ruaj propozimet e zgjedhura";apply.onclick=async()=>{const selected=[...lessonAgentProposals.querySelectorAll("input:checked")].map(input=>pendingLessonProposals[Number(input.dataset.proposal)]);if(!selected.length){lessonAgentStatus.textContent="Zgjidh të paktën një propozim.";return}apply.disabled=true;try{const saved=await fetch("/api/agent/apply",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${lessonAgentKey}`},body:JSON.stringify({proposals:selected})});const result=await saved.json();if(!saved.ok)throw new Error(result.error||"Ruajtja dështoi.");lessonAgentStatus.textContent=`U ruajtën ${result.saved} propozime.`;await loadAgentLessons();}catch(error){lessonAgentStatus.textContent=error.message}finally{apply.disabled=false}};lessonAgentProposals.append(apply);lessonAgentStatus.textContent="Shqyrto propozimet, pastaj zgjidh cilat të ruash."}catch(error){lessonAgentStatus.textContent=error.message;if(error.message.includes("Çelësi i redaktorit")){sessionStorage.removeItem("cyberedu_lesson_agent_key");lessonAgentKey=""}}finally{button.disabled=false}
};

document.getElementById("lesson-agent-auto").onclick=async()=>{
  if(!lessonAgentKey){lessonAgentKey=prompt("Vendos çelësin e redaktorit të konfiguruar në server (LESSON_AGENT_KEY):")||"";if(lessonAgentKey)sessionStorage.setItem("cyberedu_lesson_agent_key",lessonAgentKey)}
  if(!lessonAgentKey){lessonAgentStatus.textContent="Mungon çelësi i redaktorit.";return}
  const button=document.getElementById("lesson-agent-auto"),manual=document.getElementById("lesson-agent-generate"),excluded=new Set();let changed=0;
  button.disabled=true;manual.disabled=true;lessonAgentProposals.replaceChildren();
  try{
    const catalog=lessons.map(lesson=>({...lesson,agentChapters:getLessonChapters(lesson),sources:lesson.sources||lessonSources[lesson.id]||[]}));
    lessonAgentStatus.textContent="Po përgatitet katalogu për ruajtje të sigurt…";
    const sync=await fetch("/api/agent/sync",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${lessonAgentKey}`},body:JSON.stringify({lessons:catalog})}),syncResult=await sync.json();if(!sync.ok)throw new Error(syncResult.error||"Ruajtja e kursit dështoi.");
    for(let round=1;round<=3;round++){
      lessonAgentStatus.textContent=`AI po kontrollon kursin (${round}/3)…`;
      const request=`Bëj një auditim të plotë dhe autonom të mësimeve të sigurisë kibernetike. Kontrollo saktësinë, qartësinë, këshillat e vjetruara, përsëritjet dhe temat e rëndësishme që mungojnë. Përmirëso vetëm mësimet që kanë problem real dhe shto tema të reja vetëm kur mbulojnë një boshllëk të dobishëm. Mos e ndrysho temën pa nevojë. IDs që janë rishikuar tashmë në këtë auditim dhe duhen lënë të paprekura: ${[...excluded].join(", ")||"asnjë"}. Nëse nuk ka përmirësime ose tema të reja me vlerë, kthe listë bosh.`;
      const currentCatalog=lessons.map(lesson=>({...lesson,agentChapters:getLessonChapters(lesson),sources:lesson.sources||lessonSources[lesson.id]||[]}));
      const response=await fetch("/api/agent/propose",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${lessonAgentKey}`},body:JSON.stringify({request,lessons:currentCatalog})}),result=await response.json();
      if(!response.ok)throw new Error(result.error||"Auditimi dështoi.");
      if(!result.proposals?.length){lessonAgentStatus.textContent=changed?`Auditimi mbaroi. AI ruajti ${changed} ndryshime.`:"Auditimi mbaroi. AI nuk gjeti ndryshime të nevojshme.";return}
      for(const proposal of result.proposals){if(proposal.operation==="update")excluded.add(proposal.targetId);else excluded.add(proposal.lesson.id)}
      const saved=await fetch("/api/agent/apply",{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${lessonAgentKey}`},body:JSON.stringify({proposals:result.proposals})}),saveResult=await saved.json();
      if(!saved.ok)throw new Error(saveResult.error||"Ruajtja automatike dështoi.");
      changed+=saveResult.saved;await loadAgentLessons();
    }
    lessonAgentStatus.textContent=`AI ruajti ${changed} ndryshime. U arrit kufiri për këtë auditim; mund ta nisësh sërish më vonë.`;
  }catch(error){lessonAgentStatus.textContent=changed?`U ruajtën ${changed} ndryshime para gabimit: ${error.message}`:error.message;if(error.message.includes("Çelësi i redaktorit")){sessionStorage.removeItem("cyberedu_lesson_agent_key");lessonAgentKey=""}}
  finally{button.disabled=false;manual.disabled=false}
};

// Local, self-reported security check; no device or account scanning.
const checkItems=[{q:"A përdor fjalëkalime unike për llogaritë e rëndësishme?",yes:"Po, përdor fjalëkalime unike",no:"Jo ose nuk jam i sigurt"},{q:"A e ke aktivizuar verifikimin me dy hapa (MFA) kur ofrohet?",yes:"Po, e kam aktivizuar",no:"Jo ose nuk jam i sigurt"},{q:"A i instalon përditësimet e sistemit dhe aplikacioneve?",yes:"Po, rregullisht/automatikisht",no:"Jo ose i shtyj shpesh"},{q:"Kur merr mesazh urgjent me lidhje, a verifikon përmes kanalit zyrtar?",yes:"Po, kontrolloj veçmas",no:"Jo, mund të klikoj nga mesazhi"},{q:"A ruan kopje rezervë të skedarëve të rëndësishëm?",yes:"Po, kam kopje rezervë",no:"Jo ose nuk e di"}];let checkAnswers=[],checkIndex=0;
function renderCheck(){const box=document.getElementById("check-questions");box.classList.remove("hidden");if(checkIndex>=checkItems.length){const score=Math.round(checkAnswers.filter(Boolean).length/checkItems.length*100);document.getElementById("security-score").textContent=score;document.getElementById("security-score-label").textContent="PIKË";document.getElementById("score-ring").style.setProperty("--score",`${score}%`);recordActivity(`Përfundove vetëvlerësimin e sigurisë: ${score}%`);document.getElementById("security-score-note").textContent=score>=80?"Zakone të mira. Vazhdo t’i mbash.":score>=60?"Mirë, ka disa hapa të dobishëm për t’u përmirësuar.":"Fillo me MFA, përditësime dhe fjalëkalime unike.";box.innerHTML=`<b>Vetëvlerësimi përfundoi</b><p>${checkAnswers.filter(Boolean).length} nga ${checkItems.length} zakone të mira të shënuara.</p><button type="button" id="redo-check" class="secondary-btn">Plotëso sërish</button>`;document.getElementById("redo-check").onclick=()=>{checkAnswers=[];checkIndex=0;renderCheck()};return}const item=checkItems[checkIndex];box.innerHTML=`<span class="section-kicker">PYETJA ${checkIndex+1} NGA ${checkItems.length}</span><h3>${item.q}</h3><div class="check-options"><button type="button" data-check="yes">${item.yes}</button><button type="button" data-check="no">${item.no}</button></div>`;box.querySelectorAll("[data-check]").forEach(btn=>btn.onclick=()=>{checkAnswers.push(btn.dataset.check==="yes");checkIndex++;renderCheck()})}
document.getElementById("start-check").onclick=()=>{checkAnswers=[];checkIndex=0;renderCheck()};
const incidentText={link:"Mbylle faqen dhe mos shkarko apo plotëso asgjë tjetër. Nëse ke futur të dhëna, ndrysho fjalëkalimin nga faqja zyrtare dhe kontrollo sesionet e llogarisë.",password:"Hape shërbimin duke shkruar vetë adresën zyrtare, ndrysho fjalëkalimin menjëherë dhe dil nga sesionet e panjohura. Ndryshoje edhe kudo ku e ke ripërdorur; aktivizo MFA.",payment:"Kontakto bankën menjëherë përmes numrit në kartë ose aplikacionit zyrtar. Kërko bllokimin/monitorimin e pagesës dhe ruaj mesazhet si provë."};document.querySelectorAll("[data-incident]").forEach(btn=>btn.onclick=()=>{document.getElementById("incident-guidance").textContent=incidentText[btn.dataset.incident];document.querySelectorAll("[data-incident]").forEach(b=>b.classList.toggle("active",b===btn))});
