let labIndex=0,labScore=0;
function renderLabCase(){const item=labCases[labIndex];if(!item)return;document.getElementById("lab-case-number").textContent=String(labIndex+1).padStart(2,"0");document.getElementById("lab-case-total").textContent=String(labCases.length).padStart(2,"0");document.getElementById("lab-progress-bar").style.width=`${(labIndex+1)/labCases.length*100}%`;document.getElementById("lab-case-title").textContent=item.title;document.getElementById("lab-sender").textContent=item.sender;document.getElementById("lab-message").textContent=item.message;document.getElementById("lab-feedback").textContent="";document.getElementById("lab-feedback").className="lab-feedback";document.getElementById("lab-next").classList.add("hidden");document.getElementById("lab-choices").innerHTML=item.options.map((choice,index)=>`<button type="button" class="lab-choice" data-lab-choice="${index}">${choice}</button>`).join("");document.querySelectorAll("[data-lab-choice]").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll("[data-lab-choice]").forEach(choice=>choice.disabled=true);const correct=Number(button.dataset.labChoice)===item.correct;if(correct){labScore+=10;document.getElementById("lab-score").textContent=labScore;button.classList.add("correct")}else{button.classList.add("wrong");document.querySelector(`[data-lab-choice="${item.correct}"]`).classList.add("correct")}const feedback=document.getElementById("lab-feedback");feedback.textContent=(correct?"✓ Zgjedhje e sigurt. ":"⚠ Mund të jetë e rrezikshme. ")+item.feedback;feedback.classList.add(correct?"good":"careful");document.getElementById("lab-next").classList.remove("hidden")}))}
document.getElementById("lab-next").addEventListener("click",()=>{if(labIndex<labCases.length-1){labIndex++;renderLabCase()}else{recordActivity(`Përfundove laboratorin: ${labScore} nga ${labCases.length*10} pikë`);document.getElementById("lab-case-title").textContent="Laboratori përfundoi!";document.getElementById("lab-choices").innerHTML="";document.getElementById("lab-message").textContent=`Rezultati yt është ${labScore} nga ${labCases.length*10} pikë. Rifillo për të praktikuar përsëri.`;document.querySelector(".lab-question").textContent="Urime për përfundimin e simulimeve.";document.getElementById("lab-feedback").textContent="Mbaj mend: ndalo, verifiko dërguesin dhe përdor kanalet zyrtare.";document.getElementById("lab-next").classList.add("hidden")}});
document.getElementById("lab-restart").addEventListener("click",()=>{labIndex=0;labScore=0;document.getElementById("lab-score").textContent="0";document.querySelector(".lab-question").textContent="Çfarë do të bëje në këtë situatë?";renderLabCase()});
renderLabCase();
